export const isSubDomain = (hostname: string, domain: string) => {
    if (hostname === domain) {
        return true;
    }

    return hostname.endsWith(`.${domain}`);
};

export const getHostname = (url: string) => {
    // The easy way to parse an URL, is to create <a> element.
    // @see: https://gist.github.com/jlong/2428561
    const parser = document.createElement('a');
    parser.href = url;
    return parser.hostname;
};

/** Extract the domain label immediately before the final suffix. */
export const getHostnameWithRegex = (url: string): string => {
    const match =
        /^(?:(?:[a-z][a-z\d+.-]*:)?\/\/(?:[^/?#@]*@)?)?(?:[^./:?#@]+\.)*([^./:?#@]+)\.[^./:?#@]+(?::\d+)?(?:[/?#]|$)/i.exec(
            url
        );
    return match?.[1] || '';
};

/** Encode only the hostname, leaving the other URL components as written. */
export const punycodeUrl = (url: string): string => {
    const match = /^((?:[a-z][a-z\d+.-]*:)?\/\/)([^/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i.exec(url);
    if (!match) {
        return url;
    }

    const parsed = new URL(url, 'https://example.invalid');
    const [, prefix, authority, pathname, search = '', hash = ''] = match;
    const hostnameStart = authority.lastIndexOf('@') + 1;
    const hostAndPort = authority.slice(hostnameStart);
    const hostnameEnd = hostAndPort.startsWith('[')
        ? hostAndPort.indexOf(']') + 1
        : hostAndPort.indexOf(':') === -1
        ? hostAndPort.length
        : hostAndPort.indexOf(':');

    if (!hostnameEnd || !parsed.hostname) {
        throw new TypeError('URL has no hostname');
    }

    const asciiHostname = punycode.toASCII(parsed.hostname);
    const pathWithoutTrailingSlash = pathname.replace(/\/+$/, '');
    return `${prefix}${authority.slice(0, hostnameStart)}${asciiHostname}${hostAndPort.slice(
        hostnameEnd
    )}${pathWithoutTrailingSlash}${search}${hash}`;
};

export const isMailTo = (url: string): boolean => {
    return url.toLowerCase().startsWith('mailto:');
};

export const isExternal = (url: string) => {
    try {
        return window.location.hostname !== getHostname(url) && !isMailTo(url);
    } catch (e: any) {
        /*
         * IE11/Edge are the worst, they crash when they try to parse
         * ex: http://xn--rotonmail-4sg.com
         * so if it does we know it's an external link (⌐■_■)
         */
        return true;
    }
